defmodule CodexPoolerWeb.Admin.UpstreamsLive.WorkflowError do
  @moduledoc false

  use Gettext, backend: CodexPoolerWeb.Gettext

  @spec message(term()) :: String.t()
  def message(%Ecto.Changeset{} = changeset) do
    changeset
    |> Ecto.Changeset.traverse_errors(&CodexPoolerWeb.CoreComponents.translate_error/1)
    |> Enum.flat_map(fn {field, messages} ->
      Enum.map(messages, &gettext("%{field} %{message}", field: field_label(field), message: &1))
    end)
    |> Enum.join(", ")
  end

  def message(%{code: :invalid_callback_url}), do: gettext("OAuth callback URL is invalid")
  def message(%{code: :invalid_callback_origin}), do: gettext("OAuth callback URL must use http://localhost:1455/auth/callback")
  def message(%{code: :missing_state}), do: gettext("OAuth callback is missing state")
  def message(%{code: :duplicate_callback_param}), do: gettext("OAuth callback contains duplicate parameters")
  def message(%{code: :missing_callback_result}), do: gettext("OAuth callback must include either an authorization code or provider error")
  def message(%{code: :provider_denied}), do: gettext("OpenAI denied the OAuth request")
  def message(%{code: :invalid_state}), do: gettext("OAuth callback state does not match a pending flow")
  def message(%{code: :expired_flow}), do: gettext("OAuth flow has expired")
  def message(%{code: :flow_not_pending}), do: gettext("OAuth flow is not pending")
  def message(%{code: :stale_flow}), do: gettext("OAuth flow was superseded")
  def message(%{code: :token_exchange_failed}), do: gettext("OAuth token exchange failed")
  def message(%{code: :identity_mismatch}), do: gettext("OAuth account does not match the selected upstream account")
